"""Teaching-oriented report generated by the complete runner, not a later patch."""
from evaluate import ORACLE
from methods import MODELS


def metric_definitions():
    return dict(
        main_aggregation='mean repeats per design -> mean designs per anchor workgroup -> mean workgroups',
        direction_accuracy='Focus only; unknown/ignore count as incorrect; context is supplied.',
        coverage='Fraction with similar/different at true focus. Evaluator-only identification of focus.',
        focus_macro_f1='Macro of similar/different F1 from design-weighted confusion per workgroup, then mean workgroups.',
        joint_accuracy='Correct direction and exactly one inferred non-context focus, which equals true focus.',
        ndcg='Original graded gain 2^grade-1, TF-IDF scoring; k=5,10.',
        retrieval='Original Recall/Precision/MRR: grade 1 AND grade 2 count as positive.',
        compliance='Original count(grade=2 in top K)/K; v1 ceiling .2 at K=5, .1 at K=10.',
        top1_grade2='Fraction with grade 2 at rank 1; ceiling 1.',
        importance_mae='Original mean absolute difference over five weights against true session weights.',
        legacy_summary='Actual original aggregate: equal case-condition means; pooled macro-F1 over context+focus.',
        legacy_columns='legacy_direction_* in main summary use context+focus but anchor aggregation; legacy_summary.csv uses original aggregation.',
        unknown='Raw predictions remain unknown for evaluation; common ranking fallback is not a correct prediction.',
        oracle='Evaluator-only true session directions AND weights; same intent_scores, not a mathematical upper bound.',
        inference='No training, new data, parameter search or previous prediction cache.')


def report(summary,legacy,claims,info):
    overall = {r['model']:r for r in summary if r['group']=='overall'}
    old = {r['model']:r for r in legacy if r['group']=='overall'}
    order = MODELS+(ORACLE,)
    lines = ['# Thực nghiệm D — suy nhu cầu phiên và xếp hạng bài báo', '',
        '## 1. Hai câu hỏi cần kiểm tra', '',
        '| Câu hỏi | Phép so |', '|---|---|',
        '| Query/phản ứng có giúp suy hướng không? | Không tín hiệu phiên / chỉ query / chỉ phản ứng / kết hợp |',
        '| Intent suy được có giúp ranking không? | Các dự đoán đi qua cùng policy và scorer |', '',
        'Ví dụ: giữ task gợi ý bài báo, tìm cùng hoặc khác problem so với bài mốc. Context được cung cấp; focus và hướng phải suy từ tín hiệu.', '',
        '## 2. Hình 1 — bài toán tổng quát', '', '```mermaid', 'flowchart TD',
        ' S["Bài thật + facets A silver<br/>Hồ sơ/lịch sử C mô phỏng"] --> G["Generator D<br/>Candidates, observation, phiên và tín hiệu"]',
        ' G --> O["Bài mốc/context<br/>Query + observation/phản ứng trước cutoff"]',
        ' G --> P["Candidate pool cố định<br/>Ưu tiên thật; tổng hợp phía thiếu"]',
        ' G --> H["Đáp án ẩn<br/>Focus, directions, weights và nhãn"]',
        ' O --> I["Suy directions"]',
        ' I --> R["R_active chung<br/>intent_scores gốc"]',
        ' P --> R', ' S -->|"Vector và C weights"| R',
        ' I --> E["Evaluator: intent và ranking"]', ' R --> E', ' H --> E',
        ' E --> T["Bảng toàn bộ<br/>Chỉ candidates thật<br/>Có bổ sung candidate tổng hợp"]', '```', '',
        'Đáp án ẩn chỉ đi vào evaluator. Observation tách khỏi candidates; estimator không nhận danh sách candidate pool đánh giá.', '',
        '## 3. Dữ liệu đang dùng', '',
        '| Thành phần | Nguồn và vai trò |', '|---|---|',
        '| Bài mốc/candidates thật | Corpus hiện có; facets silver A đã lọc |',
        '| Trọng số cá nhân | Tính lại từ prefix lịch sử C mô phỏng, khóa trước so sánh |',
        '| Candidate tổng hợp | Bản ghi facet ghép có ghi nguồn; chỉ bù phía còn thiếu |',
        '| Observation/query/phản ứng | D mô phỏng; observation riêng, phản ứng có nhiễu |',
        '| Nhãn và intent | Generator đặt trước; chỉ evaluator/oracle dùng |', '',
        '| Nhóm candidates | Số thiết kế | Số phiên | Thành phần mỗi pool |', '|---|---:|---:|---|']
    groups = {g:next((r for r in summary if r['group']==g and r['model']=='profile_similar'),None)
              for g in ('overall','source:real_only','source:mixed')}
    for g,label,composition in (('source:real_only','Chỉ candidates thật','20 thật'),
                                ('source:mixed','Có bổ sung tổng hợp','19 thật + 1 tổng hợp'),
                                ('overall','Toàn bộ','20 candidates/phiên')):
        r = groups[g]
        if r is None:
            continue
        lines.append(f"| {label} | {r['designs']} | {r['sessions']} | {composition} |")
    total = groups['overall']
    mixed = groups['source:mixed']
    mixed_count = mixed['designs'] if mixed else 0
    lines += ['', f"Nhóm có bổ sung gồm {mixed_count} thiết kế, với {info['validation']['synthetic_candidates']} candidate tổng hợp duy nhất; không có bộ chỉ gồm candidates tổng hợp.",
        f"{total['designs']} thiết kế trên {total['anchors']} bài mốc × 2 hướng × 3 chế độ query = {total['sessions']} phiên; 4 cặp observation/phiên. Mỗi pool: một candidate grade 2, một grade 1 và 18 grade 0.",
        f"{len(info['feedback_seeds'])} seeds × {len(info['feedback_noises'])} mức Gaussian noise {info['feedback_noises']} là các lần lặp trên cùng nội dung, không phải người dùng/nội dung độc lập mới.",
        f"Dataset: `{info['dataset']}`. Nguồn cào thêm ngoài corpus không dùng.", '',
        '## 4. Hình 2 — luồng hiện thực chạy từ đầu', '', '```mermaid', 'flowchart TD',
        ' A["prepare_source.py<br/>inputs/base_v1"] --> B["build_observation_data.py<br/>datasets/observation_v1"]',
        ' B --> V["validate_observation_data.py<br/>Kiểm tra dữ liệu đã khóa"]',
        ' V --> C["run_benchmark.py<br/>Tính profile C và vector chung"]',
        ' C --> M["methods.py + ordinal_intent.py<br/>8 phương pháp: suy lại từ tín hiệu phiên"]',
        ' M --> R["common_ranking.py<br/>R_active → intent_scores gốc"]',
        ' R --> P["Lưu public predictions<br/>Chưa đọc đáp án"]',
        ' P --> E["evaluate.py<br/>Đọc đáp án, thêm oracle_intent<br/>Chấm metrics gốc và tại focus"]',
        ' E --> T["reporting.py<br/>Bảng, phân nhóm và báo cáo"]', '```', '',
        'Runner chạy từ dataset đã khóa, không đọc kết quả cũ. Hai bước chuẩn bị nguồn/sinh dataset chỉ cần chạy khi chủ động đổi dữ liệu, không tự sinh lại trong mỗi benchmark.', '',
        '## 5. Phương pháp và ranking', '',
        '| Phương pháp | Cách suy |', '|---|---|',
        '| fixed_similar — gốc | Luôn similar, trọng số đều |',
        '| profile_similar — gốc | Luôn similar, trọng số C |',
        '| direction_behavior / DELTA — gốc | Chênh lệch phản ứng phía khác − phía giống |',
        '| direction_search / DELTA+query — gốc | DELTA + quy tắc query gốc |',
        '| query_only | Chỉ query |', '| vote | Dấu phiếu phản ứng + query |',
        '| bayes_h | Posterior từ dấu phản ứng + query |',
        '| ordinal_intent | Posterior từ mức chênh lệch, kể cả hòa + query |',
        '| oracle_intent — đặc quyền | Đáp án directions VÀ trọng số phiên; không phải đối thủ thực tế |', '',
        'Tất cả public methods không train, dùng chung candidates/vector; trừ fixed_similar, đều dùng cùng C weights. Không chọn lại tham số theo điểm lượt này.',
        'R_active: có duy nhất một focus suy được → context/focus hoạt động, facet khác ignore; chưa rõ → fallback always-similar đã công bố. Directions gốc vẫn giữ để chấm intent.', '',
        '### Scorer tính thế nào?', '',
        '| Bước | Quy tắc intent_scores gốc |', '|---|---|',
        '| Context gate | Thiếu context hoặc cosine ≤ 0: score −1 |',
        '| Similarity | S_f là cosine TF-IDF concept text từng facet, trong [0,1] |',
        '| Đổi theo hướng | similar/unknown: T_f=S_f; different: T_f=1−S_f; ignore: bỏ facet |',
        '| Tổng hợp | score = Σ(w_f × T_f) / Σw_f trên các facet đang dùng |',
        '| Thiếu facet | Candidate thiếu facet active có weight: −1; anchor thiếu: bỏ facet đó |',
        '| Fallback/hòa | Hết weights: cosine context; hòa điểm: theo ID |', '',
        '| Ví dụ context/problem weight .6, focus/method .4 | S_problem | S_method | Muốn giống method | Muốn khác method |',
        '|---|---:|---:|---:|---:|', '| A | .90 | .95 | .92 | .56 |', '| B | .85 | .20 | .59 | .83 |',
        'Đổi direction làm đổi ưu tiên A/B. Nhãn relevance dùng concept overlap, không dùng score làm đáp án.', '',
        '## 6. Kết quả chính — trung bình theo nhóm bài mốc', '',
        '| Method | Accuracy focus | F1 focus | Coverage focus | nDCG@10 | Grade-2@1 |',
        '|---|---:|---:|---:|---:|---:|']
    for m in order:
        r = overall[m]
        label = m+' (đặc quyền)' if m==ORACLE else m
        lines.append(f"| {label} | {r['direction_accuracy']:.2%} | {r['focus_macro_f1']:.4f} | {r['coverage']:.2%} | {r['ndcg10']:.4f} | {r['top1_grade2']:.2%} |")
    lines += ['', 'Unknown tính sai; accuracy/coverage tại focus thật do evaluator chấm. Context cho sẵn không tính vào thành tích bảng chính. F1 từ confusion theo thiết kế trong mỗi nhóm anchor rồi lấy trung bình nhóm.',
        'Oracle dùng đúng directions và weights ẩn như README gốc; không đưa vào chọn method tốt nhất, không là trần toán học. Đặc quyền được lưu riêng trong oracle_predictions.jsonl.', '',
        '### Các độ đo gốc — định nghĩa và tổng hợp gốc', '',
        '| Method | F1 context+focus | Accuracy context+focus | Coverage context+focus | Compliance@5 | Compliance@10 | Importance MAE |',
        '|---|---:|---:|---:|---:|---:|---:|']
    for m in order:
        r = old[m]
        lines.append(f"| {m} | {r['direction_macro_f1']:.4f} | {r['direction_accuracy']:.2%} | {r['direction_coverage']:.2%} | {r['intent_compliance@5']:.4f} | {r['intent_compliance@10']:.4f} | {r['importance_mae']:.4f} |")
    lines += ['', 'Bảng này gọi evaluator/aggregate gốc: trung bình case-condition và F1 gộp confusion context+focus. Vì khác phạm vi/đơn vị tổng hợp, không so trực tiếp accuracy với bảng focus ở trên.',
        'Ví dụ always-similar: accuracy focus 50%, context+focus 75%. Đây là khác định nghĩa, không phải method đổi.',
        'Compliance@K = số grade 2 trong top K / K. Một grade 2/phiên → trần @5=.20, @10=.10; không diễn giải .10 là chỉ đạt 10% khả năng tối đa.', '',
        '### Retrieval theo quy tắc gốc', '',
        '| Method | nDCG@5 | nDCG@10 | Recall@5 / @10 | Precision@5 / @10 | MRR@5 / @10 |',
        '|---|---:|---:|---:|---:|---:|']
    for m in order:
        r = old[m]
        lines.append(f"| {m} | {r['ndcg@5']:.4f} | {r['ndcg@10']:.4f} | {r['recall@5']:.4f} / {r['recall@10']:.4f} | {r['precision@5']:.4f} / {r['precision@10']:.4f} | {r['mrr@5']:.4f} / {r['mrr@10']:.4f} |")
    lines += ['', 'Recall/Precision/MRR gốc nhận cả grade 1 và 2 là positive; candidate sai hướng vẫn có thể làm những chỉ số này cao. Vì vậy cần đọc cùng nDCG, Grade-2@1 và Compliance.', '',
        '### Phân nhóm candidates — cùng lượt chạy', '',
        '| Nhóm | Thiết kế / phiên | nDCG profile_similar | nDCG DELTA+query | nDCG Oracle |', '|---|---:|---:|---:|---:|']
    for g,label in (('overall','Toàn bộ'),('source:real_only','Chỉ candidates thật'),('source:mixed','Có bổ sung tổng hợp')):
        rows = {r['model']:r for r in summary if r['group']==g}
        if not rows:
            continue
        r = rows['profile_similar']
        lines.append(f"| {label} | {r['designs']} / {r['sessions']} | {r['ndcg10']:.4f} | {rows['direction_search']['ndcg10']:.4f} | {rows[ORACLE]['ndcg10']:.4f} |")
    lines += ['', 'Các nhóm khác focus/context nên không dùng chênh lệch giữa nhóm để quy tác động nhân quả cho tổng hợp. “Chỉ candidates thật” vẫn dùng observation và phản ứng mô phỏng.', '',
        '## 7. Kết luận và giới hạn', '',
        '| Phép so | Chỉ số | Chênh lệch | Khoảng paired 95% theo anchor |', '|---|---|---:|---:|']
    for r in claims['claims']:
        lines.append(f"| {r['comparison']} | {r['metric']} | {r['delta']:+.4f} | [{r['ci_low']:+.4f}; {r['ci_high']:+.4f}] |")
    lines += ['', f"Phương pháp public tốt nhất trên pilot: {claims['best_public_on_pilot']['ndcg10']} theo nDCG; {claims['best_public_on_pilot']['direction_accuracy']} theo accuracy hướng.",
        'Phản ứng/query và intent-aware ranking được đánh giá trong mô phỏng. Phép so với no-signal bao gồm suy scope lẫn dấu hướng; không quy toàn bộ lợi ích cho riêng dấu similar/different.',
        f"{total['anchors']} anchors, query/cặp có kiểm soát và 18 candidates ngoài context khiến phép thử thuận lợi. Chưa là kiểm chứng trên người dùng hoặc nội dung độc lập; không khẳng định novelty chỉ vì một baseline đứng đầu.",
        f"Đã chạy lại từ đầu: {info['evaluations']:,} public predictions + {info['oracle_evaluations']:,} oracle predictions. Không đọc prediction cache cũ, không sinh lại dataset, không tune ngưỡng.", '',
        '## 8. Đọc kết quả và tái lập', '',
        '| Tệp | Nội dung |', '|---|---|',
        '| summary.csv / groups.csv | Tất cả chỉ số theo thiết kế/anchor; nhóm thật/tổng hợp, query, noise, focus, direction |',
        '| legacy_summary.csv / legacy_groups.csv | Đúng cách tính/tổng hợp gốc |',
        '| predictions.jsonl | 8 phương pháp public; directions trước adapter, ranking sau adapter và legacy_ranking để audit |',
        '| oracle_predictions.jsonl | Riêng evaluator; true session weights và directions |',
        '| details.jsonl / metric_definitions.json | Chỉ số từng phiên và định nghĩa |',
        '| baseline_parity.json | Cả bốn baseline khớp runner gốc trên mọi phiên/condition trước policy mới |',
        '| paired_comparisons.csv / conclusions.json | Phép so paired, bootstrap và phạm vi kết luận |',
        '| config.json / protocol.md / manifest.json | Tham số trước chạy, kế hoạch, hashes và trạng thái |', '',
        'Chạy từ thư mục experiments:', '', '```powershell',
        'python -B scripts/exp_d/proposal/run_benchmark.py', '```', '',
        'Mỗi lượt tự chọn output mới; manifest.status=complete xác nhận hoàn tất. Không cần chạy lần lượt các runner lịch sử.', '']
    return '\n'.join(lines)
